pub(crate) const CONFIG_FILE: &str = "multirust-config.toml";

#[derive(Debug)]
pub struct Manifestation {
    installation: Components,
    target_tuple: TargetTuple,
}

#[derive(Debug)]
pub struct Changes {
    pub explicit_add_components: Vec<Component>,
    pub remove_components: Vec<Component>,
}

impl Changes {
    fn iter_add_components(&self) -> impl Iterator<Item = &Component> {
        self.explicit_add_components.iter()
    }

    fn check_invariants(&self, config: &Option<Config>) -> Result<()> {
        for component_to_add in self.iter_add_components() {
            if self.remove_components.contains(component_to_add) {
                bail!("can't both add and remove components");
            }
        }
        for component_to_remove in &self.remove_components {
            let config = config
                .as_ref()
                .expect("removing component on fresh install?");
            assert!(
                config.components.contains(component_to_remove),
                "removing package that isn't installed"
            );
        }
        Ok(())
    }
}

#[derive(PartialEq, Debug, Eq)]
pub enum UpdateStatus {
    Changed,
    Unchanged,
}

impl Manifestation {
    /// Open the install prefix for updates from a distribution
    /// channel.  The install prefix directory does not need to exist;
    /// it will be created as needed. If there's an existing install
    /// then the rust-install installation format will be verified. A
    /// bad installer version is the only reason this will fail.
    pub fn open(prefix: InstallPrefix, target_tuple: TargetTuple) -> Result<Self> {
        // TODO: validate the tuple with the existing install as well
        // as the metadata format of the existing install
        Ok(Self {
            installation: Components::open(prefix)?,
            target_tuple,
        })
    }

    /// Install or update from a given channel manifest, while
    /// selecting extension components to add or remove.
    ///
    /// `update` takes a manifest describing a release of Rust (which
    /// may be either a freshly-downloaded one, or the same one used
    /// for the previous install), as well as lists of extension
    /// components to add and remove.
    ///
    /// From that it schedules a list of components to install and
    /// to uninstall to bring the installation up to date.  It
    /// downloads the components' packages. Then in a Transaction
    /// uninstalls old packages and installs new packages, writes the
    /// distribution manifest to "rustlib/rustup-dist.toml" and a
    /// configuration containing the component name-target pairs to
    /// "rustlib/rustup-config.toml".
    ///
    /// It is *not* safe to run two updates concurrently. See
    /// https://github.com/rust-lang/rustup/issues/988 for the details.
    pub async fn update(
        self,
        new_manifest: Manifest,
        changes: Changes,
        force_update: bool,
        download_cfg: &DownloadCfg<'_>,
        toolchain: &ToolchainDesc,
        implicit_modify: bool,
    ) -> Result<UpdateStatus> {
        // Some vars we're going to need a few times
        let prefix = self.installation.prefix();
        let rel_installed_manifest_path = prefix.rel_manifest_file(DIST_MANIFEST);
        let installed_manifest_path = prefix.path().join(&rel_installed_manifest_path);

        // Create the lists of components needed for installation
        let config = self.read_config()?;
        let mut update = Update::new(&self, &new_manifest, &changes, &config)?;

        if update.nothing_changes() {
            return Ok(UpdateStatus::Unchanged);
        }

        // Validate that the requested components are available
        if let Err(e) = update.unavailable_components(&new_manifest, toolchain) {
            if !force_update {
                return Err(e);
            }
            if let Ok(RustupError::RequestedComponentsUnavailable { components, .. }) =
                e.downcast::<RustupError>()
            {
                for component in &components {
                    match &component.target {
                        Some(t) if t != &self.target_tuple => warn!(
                            "skipping unavailable component {} for target {}",
                            new_manifest.short_name(component),
                            t
                        ),
                        _ => warn!(
                            "skipping unavailable component {}",
                            new_manifest.short_name(component)
                        ),
                    }
                }
                update.drop_components_to_install(&components);
            }
        }

        const DEFAULT_MIN_NAME_WIDTH: usize = 13;
        let max_name_width = update
            .components_to_install
            .iter()
            // The same as the component name's length used in `ComponentBinary::new`
            // As it's used for status output
            .map(|component| {
                new_manifest
                    .display_name(component, &toolchain.target)
                    .len()
            })
            .max()
            .unwrap_or(0)
            .max(DEFAULT_MIN_NAME_WIDTH);

        // Download component packages and validate hashes
        let components = update
            .components_to_install
            .into_iter()
            .filter_map(|component| {
                ComponentBinary::new(
                    component,
                    &new_manifest,
                    download_cfg,
                    max_name_width,
                    &toolchain.target,
                )
            })
            .collect::<Result<Vec<_>>>()?;

        const DEFAULT_CONCURRENT_DOWNLOADS: usize = 2;
        let concurrent_downloads = download_cfg
            .process
            .concurrent_downloads()
            .unwrap_or(DEFAULT_CONCURRENT_DOWNLOADS);

        const DEFAULT_MAX_RETRIES: usize = 3;
        let max_retries: usize = download_cfg
            .process
            .var("RUSTUP_MAX_RETRIES")
            .ok()
            .and_then(|s| s.parse().ok())
            .unwrap_or(DEFAULT_MAX_RETRIES);

        // Begin transaction
        let mut tx = Transaction::new(
            prefix.clone(),
            download_cfg.tmp_cx.clone(),
            download_cfg.permit_copy_rename,
        );

        // If the previous installation was from a v1 manifest we need
        // to uninstall it first.
        tx = self.maybe_handle_v2_upgrade(&config, tx)?;

        // If there are no components installed, and we are recovering from
        // a partial installation, we can provide a more informative message.
        if !update.components_to_uninstall.is_empty() && self.installation.list()?.is_empty() {
            info!("recovering from a partially installed toolchain");
        }

        // Uninstall components
        for component in update.components_to_uninstall {
            match (implicit_modify, &component.target) {
                (true, Some(t)) if t != &self.target_tuple => {
                    info!(
                        "removing previous version of component {} for target {}",
                        new_manifest.short_name(&component),
                        t
                    );
                }
                (false, Some(t)) if t != &self.target_tuple => {
                    info!(
                        "removing component {} for target {}",
                        new_manifest.short_name(&component),
                        t
                    );
                }
                (true, _) => {
                    info!(
                        "removing previous version of component {}",
                        new_manifest.short_name(&component),
                    );
                }
                (false, _) => {
                    info!("removing component {}", new_manifest.short_name(&component));
                }
            }

            tx = self.uninstall_component(component, &new_manifest, tx)?;
        }

        if !components.is_empty() {
            match &components[..] {
                [c] => info!(
                    "downloading component {}",
                    c.manifest.short_name(&c.component),
                ),
                _ => info!("downloading {} components", components.len()),
            };

            let mut stream = InstallEvents::new(components.into_iter(), Arc::new(self));
            let mut transaction = Some(tx);
            tx = loop {
                // Refill downloads when there's capacity
                // Must live outside of `InstallEvents` because we can't write the type of future
                while stream.components.len() > 0 && stream.downloads.len() < concurrent_downloads {
                    if let Some(bin) = stream.components.next() {
                        stream.downloads.push(bin.download(max_retries));
                    }
                }

                // Trigger another installation if no other installation is in progress, as evidenced
                // by whether `transaction` is `Some` (not held by another installation task).
                stream.try_install(&mut transaction);
                match stream.next().await {
                    // Completed an installation, yielding the transaction back
                    Some(Ok(tx)) => match stream.is_done() {
                        true => break tx,
                        false => transaction = Some(tx),
                    },
                    Some(Err(e)) => return Err(e),
                    // A download completed, so we can trigger another one
                    None => {}
                }
            };

            download_cfg.clean(&stream.cleanup_downloads)?;
            drop(stream);
        }

        // Install new distribution manifest
        let new_manifest_str = new_manifest.clone().stringify()?;
        tx.modify_file(rel_installed_manifest_path)?;
        utils::write_file("manifest", &installed_manifest_path, &new_manifest_str)?;

        // Write configuration.
        //
        // NB: This configuration is mostly for keeping track of the name/target pairs
        // that identify installed components. The rust-installer metadata maintained by
        // `Components` *also* tracks what is installed, but it only tracks names, not
        // name/target. Needs to be fixed in rust-installer.
        let new_config = Config {
            components: update.final_component_list,
            ..Config::default()
        };
        let config_str = new_config.stringify()?;
        let rel_config_path = prefix.rel_manifest_file(CONFIG_FILE);
        let config_path = prefix.path().join(&rel_config_path);
        tx.modify_file(rel_config_path)?;
        utils::write_file("dist config", &config_path, &config_str)?;

        // End transaction
        tx.commit();

        Ok(UpdateStatus::Changed)
    }

    #[cfg(test)]
    pub(crate) fn uninstall(
        &self,
        manifest: &Manifest,
        tmp_cx: Arc<temp::Context>,
        permit_copy_rename: bool,
    ) -> Result<()> {
        let prefix = self.installation.prefix();

        let mut tx = Transaction::new(prefix.clone(), tmp_cx, permit_copy_rename);

        // Read configuration and delete it
        let rel_config_path = prefix.rel_manifest_file(CONFIG_FILE);
        let abs_config_path = prefix.path().join(&rel_config_path);
        let config_str = utils::read_file("dist config", &abs_config_path)?;
        let config = Config::parse(&config_str).with_context(|| RustupError::ParsingFile {
            name: "config",
            path: abs_config_path,
        })?;
        tx.remove_file("dist config", rel_config_path)?;

        for component in config.components {
            tx = self.uninstall_component(component, manifest, tx)?;
        }
        tx.commit();

        Ok(())
    }

    fn uninstall_component(
        &self,
        component: Component,
        manifest: &Manifest,
        mut tx: Transaction,
    ) -> Result<Transaction> {
        // For historical reasons, the rust-installer component
        // names are not the same as the dist manifest component
        // names. Some are just the component name some are the
        // component name plus the target tuple.
        let name = component.name();
        let short_name = component.short_name();
        if let Some(c) = self.installation.find(&name)? {
            tx = c.uninstall(tx)?;
        } else if let Some(c) = self.installation.find(short_name)? {
            tx = c.uninstall(tx)?;
        } else {
            debug!(
                "component {} not found during uninstall",
                manifest.short_name(&component),
            );
        }

        Ok(tx)
    }

    // Read the config file. Config files are presently only created
    // for v2 installations.
    pub(crate) fn read_config(&self) -> Result<Option<Config>> {
        let prefix = self.installation.prefix();
        let rel_config_path = prefix.rel_manifest_file(CONFIG_FILE);
        let config_path = prefix.path().join(rel_config_path);
        if utils::path_exists(&config_path) {
            let config_str = utils::read_file("dist config", &config_path)?;
            Ok(Some(Config::parse(&config_str).with_context(|| {
                RustupError::ParsingFile {
                    name: "Config",
                    path: config_path,
                }
            })?))
        } else {
            Ok(None)
        }
    }

    #[tracing::instrument(level = "trace")]
    pub fn load_manifest(&self) -> Result<Option<Manifest>> {
        let prefix = self.installation.prefix();
        if let Some(old_manifest_path) = prefix.dist_manifest() {
            let manifest_str = utils::read_file("installed manifest", &old_manifest_path)?;
            Ok(Some(Manifest::parse(&manifest_str).with_context(|| {
                RustupError::ParsingFile {
                    name: "manifest",
                    path: old_manifest_path,
                }
            })?))
        } else {
            Ok(None)
        }
    }

    /// Installation using the legacy v1 manifest format
    pub(crate) async fn update_v1(
        &self,
        new_manifest: &[String],
        update_hash: &Path,
        dl_cfg: &DownloadCfg<'_>,
    ) -> Result<Option<String>> {
        // If there's already a v2 installation then something has gone wrong
        if self.read_config()?.is_some() {
            return Err(anyhow!(
                "the server unexpectedly provided an obsolete version of the distribution manifest"
            ));
        }

        let url = new_manifest
            .iter()
            .find(|u| u.contains(&format!("{}{}", self.target_tuple, ".tar.gz")));
        if url.is_none() {
            return Err(anyhow!(
                "binary package was not provided for '{}'",
                self.target_tuple,
            ));
        }
        // Only replace once. The cost is inexpensive.
        let url = url
            .unwrap()
            .replace(DEFAULT_DIST_SERVER, dl_cfg.tmp_cx.dist_server.as_str());

        let component_name = "rust";
        let status = dl_cfg.status_for(component_name, component_name.len());
        let dl = dl_cfg
            .download_and_check(&url, Some(update_hash), Some(&status), ".tar.gz")
            .await?;
        if dl.is_none() {
            return Ok(None);
        };
        let (installer_file, installer_hash) = dl.unwrap();

        let prefix = self.installation.prefix();
        info!("installing component rust");

        // Begin transaction
        let mut tx = Transaction::new(prefix, dl_cfg.tmp_cx.clone(), dl_cfg.permit_copy_rename);

        // Uninstall components
        let components = self.installation.list()?;
        for component in components {
            tx = component.uninstall(tx)?;
        }

        // Install all the components in the installer
        let reader = utils::buffered(&installer_file)?;
        let temp_dir = dl_cfg.tmp_cx.new_directory()?;
        let io_executor = get_executor(
            unpack_ram(IO_CHUNK_SIZE, dl_cfg.process.unpack_ram()?),
            dl_cfg.process.io_thread_count()?,
        );
        let package =
            DirectoryPackage::compressed(reader, CompressionKind::GZip, temp_dir, io_executor)?;
        for component in package.components() {
            tx = package.install(&self.installation, &component, None, tx)?;
        }

        // End transaction
        tx.commit();

        Ok(Some(installer_hash))
    }

    // If the previous installation was from a v1 manifest, then it
    // doesn't have a configuration or manifest-derived list of
    // component/target pairs. Uninstall it using the installer's
    // component list before upgrading.
    fn maybe_handle_v2_upgrade(
        &self,
        config: &Option<Config>,
        mut tx: Transaction,
    ) -> Result<Transaction> {
        let installed_components = self.installation.list()?;
        let looks_like_v1 = config.is_none() && !installed_components.is_empty();

        if !looks_like_v1 {
            return Ok(tx);
        }

        for component in installed_components {
            tx = component.uninstall(tx)?;
        }

        Ok(tx)
    }
}

struct InstallEvents<'a, F> {
    manifestation: Arc<Manifestation>,
    components: vec::IntoIter<ComponentBinary<'a>>,
    cleanup_downloads: Vec<&'a str>,
    install_queue: VecDeque<ComponentInstall>,
    installing: Option<JoinHandle<Result<Transaction>>>,
    downloads: FuturesUnordered<F>,
}

impl<'a, F> InstallEvents<'a, F> {
    fn new(
        components: vec::IntoIter<ComponentBinary<'a>>,
        manifestation: Arc<Manifestation>,
    ) -> Self {
        Self {
            manifestation,
            cleanup_downloads: Vec::with_capacity(components.len()),
            components,
            install_queue: VecDeque::new(),
            installing: None,
            downloads: FuturesUnordered::new(),
        }
    }

    fn try_install(&mut self, tx: &mut Option<Transaction>) {
        let Some(installable) = self.install_queue.pop_front() else {
            return;
        };

        if let Some(tx) = tx.take() {
            let manifestation = self.manifestation.clone();
            self.installing = Some(spawn_blocking(|| installable.install(tx, manifestation)));
        } else {
            self.install_queue.push_front(installable);
        }
    }

    fn is_done(&self) -> bool {
        self.components.len() == 0 && self.downloads.is_empty() && self.install_queue.is_empty()
    }
}

impl<'a, F: Future<Output = Result<(ComponentInstall, &'a str)>>> Stream for InstallEvents<'a, F> {
    type Item = Result<Transaction>;

    fn poll_next(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Option<Self::Item>> {
        let mut this = self.as_mut();

        // First, see if any of the downloads is complete; if so, yield `None`
        // to the caller so it can trigger another download.
        match Pin::new(&mut this.downloads).poll_next(cx) {
            Poll::Ready(Some(Ok((installable, hash)))) => {
                this.cleanup_downloads.push(hash);
                this.install_queue.push_back(installable);
                return Poll::Ready(None);
            }
            Poll::Ready(Some(Err(e))) => return Poll::Ready(Some(Err(e))),
            Poll::Ready(None) | Poll::Pending => {}
        }

        let Some(handle) = &mut this.installing else {
            return match self.install_queue.is_empty() {
                // Nothing to do, yield control to the runtime
                true => Poll::Pending,
                // Can try to start the next installation
                false => Poll::Ready(None),
            };
        };

        match ready!(Pin::new(handle).poll(cx)) {
            Ok(Ok(tx)) => {
                // Current `handle` must not be polled again
                this.installing = None;
                Poll::Ready(Some(Ok(tx)))
            }
            Ok(Err(e)) => Poll::Ready(Some(Err(e))),
            Err(e) => Poll::Ready(Some(Err(anyhow!(
                "internal error during installation: {e}"
            )))),
        }
    }
}

#[derive(Debug, Default)]
struct Update {
    components_to_uninstall: Vec<Component>,
    components_to_install: Vec<Component>,
    final_component_list: Vec<Component>,
    missing_components: Vec<Component>,
}

impl Update {
    /// Returns components to uninstall, install, and the list of all
    /// components that will be up to date after the update.
    fn new(
        manifestation: &Manifestation,
        new_manifest: &Manifest,
        changes: &Changes,
        config: &Option<Config>,
    ) -> Result<Self> {
        // The package to install.
        let rust_package = new_manifest.get_package("rust")?;
        let rust_target_package = rust_package.get_target(Some(&manifestation.target_tuple))?;

        changes.check_invariants(config)?;

        // The list of components already installed, empty if a new install
        let mut starting_list = config
            .as_ref()
            .map(|c| c.components.clone())
            .unwrap_or_default();

        let installed_components = manifestation.installation.list()?;
        let looks_like_v1 = config.is_none() && !installed_components.is_empty();
        if looks_like_v1 {
            let mut profile_components = new_manifest
                .get_profile_components(Profile::Default, &manifestation.target_tuple)?;
            starting_list.append(&mut profile_components);
        }

        let mut result = Self::default();

        // Find the final list of components we want to be left with when
        // we're done: required components, added components, and existing
        // installed components.

        // Add requested components
        for component in &changes.explicit_add_components {
            result.final_component_list.push(component.clone());
        }

        // Add components that are already installed
        for existing_component in &starting_list {
            if changes.remove_components.contains(existing_component) {
                continue;
            }

            // If there is a rename in the (new) manifest, then we uninstall the component with the
            // old name and install a component with the new name
            if let Some(renamed_component) = new_manifest.rename_component(existing_component) {
                if !result.final_component_list.contains(&renamed_component) {
                    result.final_component_list.push(renamed_component);
                }
                continue;
            }

            if result.final_component_list.contains(existing_component) {
                continue;
            }

            if rust_target_package.components.contains(existing_component) {
                result.final_component_list.push(existing_component.clone());
                continue;
            }

            // Component not available, check if this is a case of
            // where rustup brokenly installed `rust-src` during
            // the 1.20.x series
            if !existing_component.contained_within(&rust_target_package.components) {
                result.missing_components.push(existing_component.clone());
                continue;
            }

            // It is the case, so we need to create a fresh wildcard
            // component using the package name and add it to the final
            // component list
            let wildcarded = existing_component.wildcard();
            if !result.final_component_list.contains(&wildcarded) {
                result.final_component_list.push(wildcarded);
            }
        }

        // If this is a full upgrade then the list of components to
        // uninstall is all that are currently installed, and those
        // to install the final list. It's a complete reinstall.
        //
        // If it's a modification then the components to uninstall are
        // those that are currently installed but not in the final list.
        // To install are those on the final list but not already
        // installed.
        let old_manifest = manifestation.load_manifest()?;
        let just_modifying_existing_install = old_manifest.as_ref() == Some(new_manifest);

        if just_modifying_existing_install {
            for existing_component in &starting_list {
                if !result.final_component_list.contains(existing_component) {
                    result
                        .components_to_uninstall
                        .push(existing_component.clone())
                }
            }
            for component in &result.final_component_list {
                if !starting_list.contains(component) {
                    result.components_to_install.push(component.clone());
                } else if changes.explicit_add_components.contains(component) {
                    match &component.target {
                        Some(t) if t != &manifestation.target_tuple => info!(
                            "component {} for target {} is up to date",
                            new_manifest.short_name(component),
                            t,
                        ),
                        _ => info!(
                            "component {} is up to date",
                            new_manifest.short_name(component)
                        ),
                    }
                }
            }
        } else {
            result.components_to_uninstall = starting_list;
            result
                .components_to_install
                .clone_from(&result.final_component_list);
        }

        Ok(result)
    }

    fn nothing_changes(&self) -> bool {
        self.components_to_uninstall.is_empty() && self.components_to_install.is_empty()
    }

    fn unavailable_components(
        &self,
        new_manifest: &Manifest,
        toolchain: &ToolchainDesc,
    ) -> Result<()> {
        let mut unavailable_components: Vec<Component> = self
            .components_to_install
            .iter()
            .filter(|c| {
                use crate::dist::manifest::{Package, TargetedPackage};
                let pkg: Option<&Package> = new_manifest.get_package(c.short_name()).ok();
                let target_pkg: Option<&TargetedPackage> =
                    pkg.and_then(|p| p.get_target(c.target.as_ref()).ok());
                target_pkg.map(TargetedPackage::available) != Some(true)
            })
            .cloned()
            .collect();

        unavailable_components.extend_from_slice(&self.missing_components);

        if !unavailable_components.is_empty() {
            bail!(RustupError::RequestedComponentsUnavailable {
                components: unavailable_components,
                manifest: Box::new(new_manifest.clone()),
                toolchain: toolchain.to_string(),
            });
        }

        Ok(())
    }

    fn drop_components_to_install(&mut self, to_drop: &[Component]) {
        self.components_to_install.retain(|c| !to_drop.contains(c));
        self.final_component_list.retain(|c| !to_drop.contains(c));
    }
}

struct ComponentBinary<'a> {
    component: Component,
    binary: &'a HashedBinary,
    status: DownloadStatus,
    manifest: &'a Manifest,
    download_cfg: &'a DownloadCfg<'a>,
}

impl<'a> ComponentBinary<'a> {
    fn new(
        component: Component,
        manifest: &'a Manifest,
        download_cfg: &'a DownloadCfg<'a>,
        name_width: usize,
        host_toolchain_target: &TargetTuple,
    ) -> Option<Result<Self>> {
        Some(Ok(ComponentBinary {
            binary: match manifest.binary(&component) {
                Ok(Some(b)) => b,
                Ok(None) => return None,
                Err(e) => return Some(Err(e)),
            },
            status: download_cfg.status_for(
                manifest.display_name(&component, host_toolchain_target),
                name_width,
            ),
            component,
            manifest,
            download_cfg,
        }))
    }

    async fn download(self, max_retries: usize) -> Result<(ComponentInstall, &'a str)> {
        use tokio_retry::{RetryIf, strategy::FixedInterval};

        let url = self.download_cfg.url(&self.binary.url)?;
        let installer = RetryIf::start(
            FixedInterval::from_millis(0).take(max_retries),
            || {
                self.download_cfg
                    .download(&url, &self.binary.hash, &self.status)
            },
            |e: &anyhow::Error| {
                // retry only known retriable cases
                match e.downcast_ref::<RustupError>() {
                    Some(RustupError::BrokenPartialFile)
                    | Some(RustupError::DownloadingFile { .. }) => {
                        self.status.retrying();
                        true
                    }
                    _ => false,
                }
            },
        )
        .await
        .with_context(|| {
            RustupError::ComponentDownloadFailed(self.manifest.name(&self.component))
        })?;

        let install = ComponentInstall {
            status: self.status,
            compression: self.binary.compression,
            installer,
            short_name: self.manifest.short_name(&self.component).to_owned(),
            component: self.component,
            temp_dir: self.download_cfg.tmp_cx.new_directory()?,
            io_executor: get_executor(
                unpack_ram(IO_CHUNK_SIZE, self.download_cfg.process.unpack_ram()?),
                self.download_cfg.process.io_thread_count()?,
            ),
        };

        Ok((install, &self.binary.hash))
    }
}

struct ComponentInstall {
    component: Component,
    status: DownloadStatus,
    compression: CompressionKind,
    installer: File,
    short_name: String,
    temp_dir: temp::Dir,
    io_executor: Box<dyn Executor>,
}

impl ComponentInstall {
    fn install(self, tx: Transaction, manifestation: Arc<Manifestation>) -> Result<Transaction> {
        // For historical reasons, the rust-installer component
        // names are not the same as the dist manifest component
        // names. Some are just the component name some are the
        // component name plus the target tuple.
        let pkg_name = self.component.name();
        let short_pkg_name = self.component.short_name();
        let reader = self.status.unpack(utils::buffered(&self.installer)?);
        let package = DirectoryPackage::compressed(
            reader,
            self.compression,
            self.temp_dir,
            self.io_executor,
        )?;

        // If the package doesn't contain the component that the
        // manifest says it does then somebody must be playing a joke on us.
        if !package.contains(&pkg_name, Some(short_pkg_name)) {
            return Err(RustupError::CorruptComponent(self.short_name).into());
        }

        self.status.installing();
        let tx = package.install(
            &manifestation.installation,
            &pkg_name,
            Some(short_pkg_name),
            tx,
        );
        self.status.installed();
        tx
    }
}

//! Rust distribution v2 manifests.
//!
//! This manifest describes the distributable artifacts for a single
//! release of Rust. They are toml files, typically downloaded from
//! e.g. static.rust-lang.org/dist/channel-rust-nightly.toml. They
//! describe where to download, for all platforms, each component of
//! the release, and their relationships to each other.
//!
//! Installers use this info to customize Rust installations.
//!
//! See tests/channel-rust-nightly-example.toml for an example.
//!
//! Docs: <https://forge.rust-lang.org/infra/channel-layout.html>

use std::{
    collections::{BTreeMap, btree_map::Entry},
    fmt,
    hash::{Hash, Hasher},
    str::FromStr,
};

use anyhow::{Context, Result, anyhow, bail};
use serde::{Deserialize, Serialize};

use crate::{
    dist::{Profile, TargetTuple, ToolchainDesc, config::Config},
    errors::RustupError,
    toolchain::DistributableToolchain,
};

/// A download manifest paired with its respective hash, as returned by the dist server.
pub struct ManifestWithHash {
    pub manifest: Manifest,
    pub hash: String,
}

/// Used by the `installed_components` function
pub(crate) struct ComponentStatus {
    pub component: Component,
    pub name: String,
    pub installed: bool,
    pub available: bool,
}

#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "kebab-case")]
pub struct Manifest {
    pub(crate) manifest_version: ManifestVersion,
    pub date: String,
    #[serde(default, rename = "pkg")]
    pub packages: BTreeMap<String, Package>,
    #[serde(default)]
    pub renames: BTreeMap<String, Renamed>,
    #[serde(default, skip_serializing)]
    pub reverse_renames: BTreeMap<String, String>,
    #[serde(default)]
    pub profiles: BTreeMap<Profile, Vec<String>>,
}

impl Manifest {
    pub(crate) fn display_name(&self, component: &Component, host_target: &TargetTuple) -> String {
        match &component.target {
            Some(component_target) if *host_target == *component_target => {
                self.short_name(component).to_owned()
            }
            _ => self.name(component),
        }
    }

    /// Returns the [`Component`]'s name **before** renaming, including the target if present.
    /// For the name after renaming, see [`Component::name()`].
    pub(crate) fn name(&self, component: &Component) -> String {
        let pkg = self.short_name(component);
        if let Some(t) = &component.target {
            format!("{pkg}-{t}")
        } else {
            pkg.to_owned()
        }
    }

    pub(crate) fn description(&self, component: &Component) -> String {
        let pkg = self.short_name(component);
        if let Some(t) = &component.target {
            format!("'{pkg}' for target '{t}'")
        } else {
            format!("'{pkg}'")
        }
    }

    /// Returns the [`Component`]'s short name (not including the target) **before** renaming.
    /// For the name after renaming, see [`Component::short_name()`].
    pub(crate) fn short_name<'a>(&'a self, component: &'a Component) -> &'a str {
        if let Some(from) = self.reverse_renames.get(&component.pkg) {
            from
        } else {
            &component.pkg
        }
    }
}

#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
pub struct Renamed {
    pub to: String,
}

#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
pub struct Package {
    pub version: String,
    #[serde(rename = "target")]
    pub targets: PackageTargets,
}

#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(from = "TargetsMap", into = "TargetsMap")]
pub enum PackageTargets {
    Wildcard(TargetedPackage),
    Targeted(BTreeMap<TargetTuple, TargetedPackage>),
}

#[derive(Deserialize, Serialize)]
#[serde(transparent)]
struct TargetsMap(BTreeMap<TargetTuple, TargetedPackage>);

impl From<TargetsMap> for PackageTargets {
    fn from(mut map: TargetsMap) -> Self {
        let wildcard = TargetTuple::new("*");
        match (map.0.len(), map.0.entry(wildcard)) {
            (1, Entry::Occupied(entry)) => Self::Wildcard(entry.remove()),
            (_, _) => Self::Targeted(map.0),
        }
    }
}

impl From<PackageTargets> for TargetsMap {
    fn from(targets: PackageTargets) -> Self {
        match targets {
            PackageTargets::Wildcard(tpkg) => {
                let mut map = BTreeMap::new();
                map.insert(TargetTuple::new("*"), tpkg);
                Self(map)
            }
            PackageTargets::Targeted(tpkgs) => Self(tpkgs),
        }
    }
}

#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(from = "Target", into = "Target")]
pub struct TargetedPackage {
    #[serde(default)]
    pub bins: Vec<HashedBinary>,
    pub components: Vec<Component>,
}

#[derive(Debug, Deserialize, Serialize)]
struct Target {
    available: bool,
    url: Option<String>,
    hash: Option<String>,
    xz_url: Option<String>,
    xz_hash: Option<String>,
    zst_url: Option<String>,
    zst_hash: Option<String>,
    components: Option<Vec<Component>>,
    extensions: Option<Vec<Component>>,
}

impl From<Target> for TargetedPackage {
    fn from(target: Target) -> Self {
        let mut components = target.components.unwrap_or_default();
        if let Some(extensions) = target.extensions {
            components.extend(extensions.into_iter().map(|mut c| {
                c.is_extension = true;
                c
            }));
        }

        let mut bins = Vec::new();
        if !target.available {
            return Self { bins, components };
        }

        if let (Some(url), Some(hash)) = (target.zst_url, target.zst_hash) {
            bins.push(HashedBinary {
                url,
                hash,
                compression: CompressionKind::ZStd,
            });
        }

        if let (Some(url), Some(hash)) = (target.xz_url, target.xz_hash) {
            bins.push(HashedBinary {
                url,
                hash,
                compression: CompressionKind::XZ,
            });
        }

        if let (Some(url), Some(hash)) = (target.url, target.hash) {
            bins.push(HashedBinary {
                url,
                hash,
                compression: CompressionKind::GZip,
            });
        }

        Self { bins, components }
    }
}

impl From<TargetedPackage> for Target {
    fn from(tpkg: TargetedPackage) -> Self {
        let (mut url, mut hash) = (None, None);
        let (mut xz_url, mut xz_hash) = (None, None);
        let (mut zst_url, mut zst_hash) = (None, None);
        let available = !tpkg.bins.is_empty();
        for bin in tpkg.bins {
            match bin.compression {
                CompressionKind::GZip => {
                    url = Some(bin.url);
                    hash = Some(bin.hash);
                }
                CompressionKind::XZ => {
                    xz_url = Some(bin.url);
                    xz_hash = Some(bin.hash);
                }
                CompressionKind::ZStd => {
                    zst_url = Some(bin.url);
                    zst_hash = Some(bin.hash);
                }
            }
        }

        let (mut components, mut extensions) =
            (Vec::with_capacity(tpkg.components.len()), Vec::new());
        for c in tpkg.components {
            match c.is_extension {
                true => &mut extensions,
                false => &mut components,
            }
            .push(c);
        }

        Self {
            available,
            url,
            hash,
            xz_url,
            xz_hash,
            zst_url,
            zst_hash,
            components: Some(components),
            extensions: Some(extensions),
        }
    }
}

#[derive(Clone, Copy, Debug, Deserialize, Eq, PartialEq, Serialize)]
pub enum CompressionKind {
    GZip,
    XZ,
    ZStd,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct HashedBinary {
    pub url: String,
    pub hash: String,
    pub compression: CompressionKind,
}

#[derive(Clone, Debug, Deserialize, Eq, Ord, PartialOrd, Serialize)]
pub struct Component {
    pub pkg: String,
    #[serde(with = "component_target")]
    pub target: Option<TargetTuple>,
    // Older Rustup distinguished between components (which are essential) and
    // extensions (which are not).
    #[serde(default)]
    pub is_extension: bool,
}

impl PartialEq for Component {
    fn eq(&self, other: &Self) -> bool {
        self.pkg == other.pkg && self.target == other.target
    }
}

impl Hash for Component {
    fn hash<H>(&self, hasher: &mut H)
    where
        H: Hasher,
    {
        self.pkg.hash(hasher);
        self.target.hash(hasher);
    }
}

mod component_target {
    use super::{Result, TargetTuple};
    use serde::{Deserialize, Deserializer, Serializer};

    pub fn serialize<S: Serializer>(
        target: &Option<TargetTuple>,
        serializer: S,
    ) -> Result<S::Ok, S::Error> {
        serializer.serialize_str(match target {
            Some(t) => t,
            None => "*",
        })
    }

    pub fn deserialize<'de, D: Deserializer<'de>>(
        deserializer: D,
    ) -> Result<Option<TargetTuple>, D::Error> {
        Ok(match Option::<String>::deserialize(deserializer)? {
            Some(s) if s != "*" => Some(TargetTuple::new(s)),
            _ => None,
        })
    }
}

impl Manifest {
    pub fn parse(data: &str) -> Result<Self> {
        let mut manifest = toml::from_str::<Self>(data).context("error parsing manifest")?;
        for (from, to) in manifest.renames.iter() {
            manifest.reverse_renames.insert(to.to.clone(), from.clone());
        }

        manifest.validate()?;
        Ok(manifest)
    }

    pub fn stringify(self) -> Result<String> {
        Ok(toml::to_string(&self)?)
    }

    pub(super) fn binary(&self, component: &Component) -> Result<Option<&HashedBinary>> {
        let package = self.get_package(component.short_name())?;
        let target_package = package.get_target(component.target.as_ref())?;
        // We prefer the first format in the list, since the parsing of the
        // manifest leaves us with the files/hash pairs in preference order.
        Ok(target_package.bins.first())
    }

    pub fn get_package(&self, name: &str) -> Result<&Package> {
        self.packages
            .get(name)
            .ok_or_else(|| anyhow!(format!("package not found: '{name}'")))
    }

    pub(crate) fn get_rust_version(&self) -> Result<&str> {
        self.get_package("rust").map(|p| &*p.version)
    }

    pub(crate) fn get_legacy_components(&self, target: &TargetTuple) -> Result<Vec<Component>> {
        // Build a profile from the components/extensions.
        let result = self
            .get_package("rust")?
            .get_target(Some(target))?
            .components
            .iter()
            .filter(|c| !c.is_extension && c.target.as_ref().map(|t| t == target).unwrap_or(true))
            .cloned()
            .collect();

        Ok(result)
    }
    pub fn get_profile_components(
        &self,
        profile: Profile,
        target: &TargetTuple,
    ) -> Result<Vec<Component>> {
        // An older manifest with no profiles section.
        if self.profiles.is_empty() {
            return self.get_legacy_components(target);
        }

        let profile = self
            .profiles
            .get(&profile)
            .ok_or_else(|| anyhow!(format!("profile not found: '{profile}'")))?;

        let rust_pkg = self.get_package("rust")?.get_target(Some(target))?;
        let result = profile
            .iter()
            .map(|s| {
                (
                    s,
                    rust_pkg.components.iter().find(|c| {
                        &c.pkg == s && c.target.as_ref().map(|t| t == target).unwrap_or(true)
                    }),
                )
            })
            .filter(|(_, c)| c.is_some())
            .map(|(s, c)| Component::new(s.to_owned(), c.and_then(|c| c.target.clone()), false))
            .collect();
        Ok(result)
    }

    fn validate_targeted_package(&self, tpkg: &TargetedPackage) -> Result<()> {
        for c in tpkg.components.iter() {
            let cpkg = self.get_package(&c.pkg).with_context(|| {
                RustupError::MissingPackageForComponent(self.short_name(c).to_owned())
            })?;
            let _ctpkg = cpkg.get_target(c.target.as_ref()).with_context(|| {
                RustupError::MissingPackageForComponent(self.short_name(c).to_owned())
            })?;
        }
        Ok(())
    }

    fn validate(&self) -> Result<()> {
        // Every component mentioned must have an actual package to download
        for pkg in self.packages.values() {
            match &pkg.targets {
                PackageTargets::Wildcard(tpkg) => {
                    self.validate_targeted_package(tpkg)?;
                }
                PackageTargets::Targeted(tpkgs) => {
                    for tpkg in tpkgs.values() {
                        self.validate_targeted_package(tpkg)?;
                    }
                }
            }
        }

        // The target of any renames must be an actual package. The subject of
        // renames is unconstrained.
        for renamed in self.renames.values() {
            let name = &renamed.to;
            if !self.packages.contains_key(name) {
                bail!(format!(
                    "server sent a broken manifest: missing package for the target of a rename {name}"
                ));
            }
        }

        Ok(())
    }

    // If the component should be renamed by this manifest, then return a new
    // component with the new name. If not, return `None`.
    pub(crate) fn rename_component(&self, component: &Component) -> Option<Component> {
        self.renames.get(&component.pkg).map(|r| {
            let mut c = component.clone();
            c.pkg.clone_from(&r.to);
            c
        })
    }

    /// Determine installed components from an installed manifest.
    pub(crate) fn query_components(
        &self,
        desc: &ToolchainDesc,
        config: &Config,
    ) -> Result<Vec<ComponentStatus>> {
        // Return all optional components of the "rust" package for the
        // toolchain's target tuple.
        let mut res = Vec::new();

        let rust_pkg = self
            .packages
            .get("rust")
            .expect("manifest should contain a rust package");
        let targ_pkg = rust_pkg
            .targets
            .get(&desc.target)
            .expect("installed manifest should have a known target");

        for component in &targ_pkg.components {
            let installed = component.contained_within(&config.components);

            let component_target = TargetTuple::new(component.target());

            // Get the component so we can check if it is available
            let component_pkg = self
                .get_package(component.short_name())
                .unwrap_or_else(|_| {
                    panic!(
                        "manifest should contain component {}",
                        self.short_name(component)
                    )
                });
            let component_target_pkg = component_pkg
                .targets
                .get(&component_target)
                .expect("component should have target toolchain");

            res.push(ComponentStatus {
                component: component.clone(),
                name: self.name(component),
                installed,
                available: component_target_pkg.available(),
            });
        }

        res.sort_by(|a, b| a.component.cmp(&b.component));

        Ok(res)
    }
}

impl Package {
    pub fn get_target(&self, target: Option<&TargetTuple>) -> Result<&TargetedPackage> {
        match &self.targets {
            PackageTargets::Wildcard(tpkg) => Ok(tpkg),
            PackageTargets::Targeted(tpkgs) => {
                if let Some(t) = target {
                    tpkgs
                        .get(t)
                        .ok_or_else(|| anyhow!(format!("target '{t}' not found in channel.  \
                        Perhaps check https://doc.rust-lang.org/nightly/rustc/platform-support.html for available targets")))
                } else {
                    Err(anyhow!("no target specified"))
                }
            }
        }
    }
}

impl PackageTargets {
    pub(crate) fn get<'a>(&'a self, target: &TargetTuple) -> Option<&'a TargetedPackage> {
        match self {
            Self::Wildcard(tpkg) => Some(tpkg),
            Self::Targeted(tpkgs) => tpkgs.get(target),
        }
    }
    pub fn get_mut<'a>(&'a mut self, target: &TargetTuple) -> Option<&'a mut TargetedPackage> {
        match self {
            Self::Wildcard(tpkg) => Some(tpkg),
            Self::Targeted(tpkgs) => tpkgs.get_mut(target),
        }
    }
}

impl TargetedPackage {
    pub fn available(&self) -> bool {
        !self.bins.is_empty()
    }
}

impl Component {
    pub fn new(pkg: String, target: Option<TargetTuple>, is_extension: bool) -> Self {
        Self {
            pkg,
            target,
            is_extension,
        }
    }

    pub(crate) fn try_new(
        name: &str,
        distributable: &DistributableToolchain<'_>,
        fallback_target: Option<&TargetTuple>,
    ) -> Result<Self> {
        let manifest = distributable.get_manifest()?;
        for component_status in distributable.components()? {
            let component = component_status.component;
            if name == component.name() || name == manifest.name(&component) {
                return Ok(component);
            }
        }

        Ok(Self::new(name.to_string(), fallback_target.cloned(), true))
    }

    pub(crate) fn wildcard(&self) -> Self {
        Self {
            pkg: self.pkg.clone(),
            target: None,
            is_extension: false,
        }
    }

    /// Returns the [`Component`]'s short name (not including the target) **after** renaming.
    /// For the name before renaming, see [`Manifest::short_name()`].
    pub fn short_name(&self) -> &String {
        &self.pkg
    }
    /// Returns the [`Component`]'s name **after** renaming, including the target if present.
    /// For the short name before renaming, see [`Manifest::name()`].
    pub(crate) fn name(&self) -> String {
        let pkg = self.short_name();
        if let Some(t) = &self.target {
            format!("{pkg}-{t}")
        } else {
            pkg.to_string()
        }
    }
    pub(crate) fn target(&self) -> String {
        if let Some(t) = self.target.as_ref() {
            t.to_string()
        } else {
            String::new()
        }
    }

    pub(crate) fn contained_within(&self, components: &[Self]) -> bool {
        if components.contains(self) {
            // Yes, we're within the component set, move on
            true
        } else if self.target.is_none() {
            // We weren't in the given component set, but we're a package
            // which targets "*" and as such older rustups might have
            // accidentally made us target specific due to a bug in profiles.
            components
                .iter()
                // As such, if our target is None, it's sufficient to check pkg
                .any(|other| other.pkg == self.pkg)
        } else {
            // As a last ditch effort, we're contained within the component
            // set if the name matches and the other component's target
            // is None
            components
                .iter()
                .any(|other| other.pkg == self.pkg && other.target.is_none())
        }
    }
}

#[derive(Clone, Copy, Debug, Default, Deserialize, Eq, PartialEq, Serialize)]
pub(crate) enum ManifestVersion {
    #[serde(rename = "2")]
    #[default]
    V2,
}

impl ManifestVersion {
    pub fn as_str(&self) -> &'static str {
        match self {
            Self::V2 => "2",
        }
    }
}

impl FromStr for ManifestVersion {
    type Err = RustupError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s {
            "2" => Ok(Self::V2),
            _ => Err(RustupError::UnsupportedVersion(s.to_owned())),
        }
    }
}

impl fmt::Display for ManifestVersion {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.as_str())
    }
}

#[cfg(test)]
mod tests {
    use crate::RustupError;
    use crate::dist::TargetTuple;
    use crate::dist::manifest::Manifest;

    // Example manifest from https://public.etherpad-mozilla.org/p/Rust-infra-work-week
    static EXAMPLE: &str = include_str!("manifest/tests/channel-rust-nightly-example.toml");
    // Same manifest as above, but with the packages in a different order.
    static EXAMPLE_REORDERED: &str =
        include_str!("manifest/tests/channel-rust-nightly-example-reordered.toml");
    // From brson's live build-rust-manifest.py script
    static EXAMPLE2: &str = include_str!("manifest/tests/channel-rust-nightly-example2.toml");

    #[test]
    fn parse_smoke_test() {
        let x86_64_unknown_linux_gnu = TargetTuple::new("x86_64-unknown-linux-gnu");
        let x86_64_unknown_linux_musl = TargetTuple::new("x86_64-unknown-linux-musl");

        let pkg = Manifest::parse(EXAMPLE).unwrap();

        pkg.get_package("rust").unwrap();
        pkg.get_package("rustc").unwrap();
        pkg.get_package("cargo").unwrap();
        pkg.get_package("rust-std").unwrap();
        pkg.get_package("rust-docs").unwrap();

        let rust_pkg = pkg.get_package("rust").unwrap();
        assert!(rust_pkg.version.contains("1.3.0"));

        let rust_target_pkg = rust_pkg
            .get_target(Some(&x86_64_unknown_linux_gnu))
            .unwrap();
        assert!(rust_target_pkg.available());
        assert_eq!(rust_target_pkg.bins[0].url, "example.com");
        assert_eq!(rust_target_pkg.bins[0].hash, "...");

        let component = &rust_target_pkg.components[0];
        assert_eq!(component.short_name(), "rustc");
        assert_eq!(component.target.as_ref(), Some(&x86_64_unknown_linux_gnu));

        let component = &rust_target_pkg.components[4];
        assert_eq!(component.short_name(), "rust-std");
        assert_eq!(component.target.as_ref(), Some(&x86_64_unknown_linux_musl));

        let docs_pkg = pkg.get_package("rust-docs").unwrap();
        let docs_target_pkg = docs_pkg
            .get_target(Some(&x86_64_unknown_linux_gnu))
            .unwrap();
        assert_eq!(docs_target_pkg.bins[0].url, "example.com");
    }

    #[test]
    fn renames() {
        let manifest = Manifest::parse(EXAMPLE2).unwrap();
        assert_eq!(1, manifest.renames.len());
        assert_eq!(manifest.renames["cargo-old"].to, "cargo");
        assert_eq!(1, manifest.reverse_renames.len());
        assert_eq!(manifest.reverse_renames["cargo"], "cargo-old");
    }

    #[test]
    fn parse_round_trip() {
        let original = Manifest::parse(EXAMPLE).unwrap();
        let serialized = original.clone().stringify().unwrap();
        let new = Manifest::parse(&serialized).unwrap();
        assert_eq!(original, new);

        let original = Manifest::parse(EXAMPLE2).unwrap();
        let serialized = original.clone().stringify().unwrap();
        let new = Manifest::parse(&serialized).unwrap();
        assert_eq!(original, new);
    }

    #[test]
    fn validate_components_have_corresponding_packages() {
        let manifest = r#"
manifest-version = "2"
date = "2015-10-10"
[pkg.rust]
  version = "rustc 1.3.0 (9a92aaf19 2015-09-15)"
  [pkg.rust.target.x86_64-unknown-linux-gnu]
    available = true
    url = "example.com"
    hash = "..."
    [[pkg.rust.target.x86_64-unknown-linux-gnu.components]]
      pkg = "rustc"
      target = "x86_64-unknown-linux-gnu"
    [[pkg.rust.target.x86_64-unknown-linux-gnu.extensions]]
      pkg = "rust-std"
      target = "x86_64-unknown-linux-musl"
[pkg.rustc]
  version = "rustc 1.3.0 (9a92aaf19 2015-09-15)"
  [pkg.rustc.target.x86_64-unknown-linux-gnu]
    available = true
    url = "example.com"
    hash = "..."
"#;

        let err = Manifest::parse(manifest).unwrap_err();

        match err.downcast::<RustupError>().unwrap() {
            RustupError::MissingPackageForComponent(_) => {}
            _ => panic!(),
        }
    }

    // #248
    #[test]
    fn manifest_can_contain_unknown_targets() {
        let manifest = EXAMPLE.replace("x86_64-unknown-linux-gnu", "mycpu-myvendor-myos");

        assert!(Manifest::parse(&manifest).is_ok());
    }

    // #4715
    #[test]
    fn manifest_serialized_with_sorted_keys() -> anyhow::Result<()> {
        let manifest = Manifest::parse(EXAMPLE)?;
        let manifest_reordered = Manifest::parse(EXAMPLE_REORDERED)?;
        assert_eq!(manifest.stringify()?, manifest_reordered.stringify()?);
        Ok(())
    }
}

//! An interpreter for the rust-installer package format.  Responsible
//! for installing from a directory or tarball to an installation
//! prefix, represented by a `Components` instance.

use std::collections::{HashMap, HashSet};
use std::io::{self, BufRead, ErrorKind as IOErrorKind, Read};
use std::mem;
use std::ops::Deref;
use std::path::{Path, PathBuf};

use anyhow::{Context, Result, anyhow, bail};
use tar::EntryType;
use tracing::warn;

use crate::diskio::{ChunkWriter, CompletedIo, Executor, IO_CHUNK_SIZE, Item, Kind};
use crate::dist::component::components::{ComponentPart, ComponentPartKind, Components};
use crate::dist::component::transaction::Transaction;
use crate::dist::manifest::CompressionKind;
use crate::dist::temp;
use crate::errors::RustupError;
use crate::utils;

/// The current metadata revision used by rust-installer
pub(crate) const INSTALLER_VERSION: &str = "3";
pub(crate) const VERSION_FILE: &str = "rust-installer-version";

#[derive(Debug)]
pub struct DirectoryPackage<P> {
    path: P,
    components: HashSet<String>,
    copy: bool,
}

impl DirectoryPackage<temp::Dir> {
    pub(crate) fn compressed<R: BufRead>(
        stream: R,
        kind: CompressionKind,
        temp_dir: temp::Dir,
        io_executor: Box<dyn Executor>,
    ) -> Result<Self> {
        match kind {
            CompressionKind::GZip => Self::from_tar(
                flate2::bufread::GzDecoder::new(stream),
                temp_dir,
                io_executor,
            ),
            CompressionKind::ZStd => Self::from_tar(
                zstd::stream::read::Decoder::with_buffer(stream)?,
                temp_dir,
                io_executor,
            ),
            CompressionKind::XZ => {
                Self::from_tar(xz2::bufread::XzDecoder::new(stream), temp_dir, io_executor)
            }
        }
    }

    fn from_tar(
        stream: impl Read,
        temp_dir: temp::Dir,
        io_executor: Box<dyn Executor>,
    ) -> Result<Self> {
        let mut archive = tar::Archive::new(stream);

        // The rust-installer packages unpack to a directory called
        // $pkgname-$version-$target. Skip that directory when
        // unpacking.
        unpack_without_first_dir(&mut archive, &temp_dir, io_executor)
            .context("failed to extract package")?;

        Self::new(temp_dir, false)
    }
}

impl<P: Deref<Target = Path>> DirectoryPackage<P> {
    pub fn new(path: P, copy: bool) -> Result<Self> {
        let file = utils::read_file("installer version", &path.join(VERSION_FILE))?;
        let v = file.trim();
        if v != INSTALLER_VERSION {
            return Err(anyhow!(format!("unsupported installer version: {v}")));
        }

        let content = utils::read_file("package components", &path.join("components"))?;
        let components = content.lines().map(ToOwned::to_owned).collect();
        Ok(Self {
            path,
            components,
            copy,
        })
    }

    pub fn contains(&self, component: &str, short_name: Option<&str>) -> bool {
        self.components.contains(component)
            || if let Some(n) = short_name {
                self.components.contains(n)
            } else {
                false
            }
    }

    pub fn install(
        &self,
        target: &Components,
        name: &str,
        short_name: Option<&str>,
        tx: Transaction,
    ) -> Result<Transaction> {
        let actual_name = if self.components.contains(name) {
            name
        } else if let Some(n) = short_name {
            n
        } else {
            name
        };

        let root = self.path.join(actual_name);

        let manifest = utils::read_file("package manifest", &root.join("manifest.in"))?;
        let mut builder = target.add(name, tx);

        for l in manifest.lines() {
            let part = ComponentPart::decode(l)
                .ok_or_else(|| RustupError::CorruptComponent(name.to_owned()))?;

            let path = part.path;
            let src_path = root.join(&path);

            match part.kind {
                ComponentPartKind::File => {
                    if self.copy {
                        builder.copy_file(path.clone(), &src_path)?
                    } else {
                        builder.move_file(path.clone(), &src_path)?
                    }
                }
                ComponentPartKind::Dir => {
                    if self.copy {
                        builder.copy_dir(path.clone(), &src_path)?
                    } else {
                        builder.move_dir(path.clone(), &src_path)?
                    }
                }
                _ => return Err(RustupError::CorruptComponent(name.to_owned()).into()),
            }
        }

        let tx = builder.finish()?;

        Ok(tx)
    }

    pub(crate) fn components(&self) -> Vec<String> {
        self.components.iter().cloned().collect()
    }
}

/// Handle the async result of io operations
/// Replaces op.result with Ok(())
fn filter_result(op: &mut CompletedIo) -> io::Result<()> {
    if let CompletedIo::Item(op) = op {
        let result = mem::replace(&mut op.result, Ok(()));
        match result {
            Ok(_) => Ok(()),
            Err(e) => match e.kind() {
                IOErrorKind::AlreadyExists => {
                    // mkdir of e.g. ~/.rustup already existing is just fine;
                    // for others it would be better to know whether it is
                    // expected to exist or not -so put a flag in the state.
                    match op.kind {
                        Kind::Directory => Ok(()),
                        _ => Err(e),
                    }
                }
                _ => Err(e),
            },
        }
    } else {
        Ok(())
    }
}

/// Dequeue the children of directories queued up waiting for the directory to
/// be created.
///
/// Currently the volume of queued items does not count as backpressure against
/// the main tar extraction process.
/// Returns the number of triggered children
fn trigger_children(
    io_executor: &dyn Executor,
    directories: &mut HashMap<PathBuf, DirStatus>,
    op: CompletedIo,
) -> Result<usize> {
    let mut result = 0;
    if let CompletedIo::Item(item) = op
        && let Kind::Directory = item.kind
    {
        let mut pending = Vec::new();
        directories
            .entry(item.full_path)
            .and_modify(|status| match status {
                DirStatus::Exists => unreachable!(),
                DirStatus::Pending(pending_inner) => {
                    pending.append(pending_inner);
                    *status = DirStatus::Exists;
                }
            })
            .or_insert_with(|| unreachable!());
        result += pending.len();
        for pending_item in pending.into_iter() {
            for mut item in io_executor.execute(pending_item).collect::<Vec<_>>() {
                // TODO capture metrics
                filter_result(&mut item)?;
                result += trigger_children(io_executor, directories, item)?;
            }
        }
    };
    Ok(result)
}

/// What is the status of this directory ?
enum DirStatus {
    Exists,
    Pending(Vec<Item>),
}

fn unpack_without_first_dir<R: Read>(
    archive: &mut tar::Archive<R>,
    path: &Path,
    mut io_executor: Box<dyn Executor>,
) -> Result<()> {
    let entries = archive.entries()?;
    let mut directories: HashMap<PathBuf, DirStatus> = HashMap::new();
    // Path is presumed to exist. Call it a precondition.
    directories.insert(path.to_owned(), DirStatus::Exists);

    'entries: for entry in entries {
        // drain completed results to keep memory pressure low and respond
        // rapidly to completed events even if we couldn't submit work (because
        // our unpacked item is pending dequeue)
        for mut item in io_executor.completed().collect::<Vec<_>>() {
            // TODO capture metrics
            filter_result(&mut item)?;
            trigger_children(&*io_executor, &mut directories, item)?;
        }

        let mut entry = entry?;
        let relpath = {
            let path = entry.path();
            let path = path?;
            path.into_owned()
        };
        // Reject path components that are not normal (..|/| etc)
        for part in relpath.components() {
            match part {
                // Some very early rust tarballs include a "." segment which we have to
                // support, despite not liking it.
                std::path::Component::Normal(_) | std::path::Component::CurDir => {}
                _ => bail!(format!("tar path '{}' is not supported", relpath.display())),
            }
        }
        let mut components = relpath.components();
        // Throw away the first path component: our root was supplied.
        components.next();
        let full_path = path.join(components.as_path());
        if full_path == path {
            // The tmp dir code makes the root dir for us.
            continue;
        }

        struct SenderEntry<'a, R: Read> {
            sender: Box<dyn ChunkWriter>,
            entry: tar::Entry<'a, R>,
        }

        /// true if either no sender_entry was provided, or the incremental file
        /// has been fully dispatched.
        fn flush_ios<R: Read, P: AsRef<Path>>(
            io_executor: &mut dyn Executor,
            directories: &mut HashMap<PathBuf, DirStatus>,
            mut sender_entry: Option<&mut SenderEntry<'_, R>>,
            full_path: P,
        ) -> Result<bool> {
            let mut result = sender_entry.is_none();
            for mut op in io_executor.completed().collect::<Vec<_>>() {
                // TODO capture metrics
                filter_result(&mut op)?;
                trigger_children(&*io_executor, directories, op)?;
            }
            // Maybe stream a file incrementally
            if let Some(sender) = sender_entry.as_mut()
                && io_executor.buffer_available(IO_CHUNK_SIZE)
            {
                let mut buffer = io_executor.get_buffer(IO_CHUNK_SIZE);
                let len = sender
                    .entry
                    .by_ref()
                    .take(IO_CHUNK_SIZE as u64)
                    .read_to_end(&mut buffer)?;
                buffer = buffer.finished();
                if len == 0 {
                    result = true;
                }
                if !sender.sender.submit(buffer) {
                    bail!(format!(
                        "IO receiver for '{}' disconnected",
                        full_path.as_ref().display()
                    ))
                }
            }
            Ok(result)
        }

        // Bail out if we get hard links, device nodes or any other unusual content
        // - it is most likely an attack, as rusts cross-platform nature precludes
        // such artifacts
        let kind = entry.header().entry_type();
        // https://github.com/rust-lang/rustup/issues/1140 and before that
        // https://github.com/rust-lang/rust/issues/25479
        // tl;dr: code got convoluted and we *may* have damaged tarballs out
        // there.
        // However the mandate we have is very simple: unpack as the current
        // user with modes matching the tar contents. No documented tars with
        // bad modes are in the bug tracker : the previous permission splatting
        // code was inherited from interactions with sudo that are best
        // addressed outside of rustup (run with an appropriate effective uid).
        // THAT SAID: If regressions turn up immediately post release this code -
        // https://play.rust-lang.org/?version=stable&mode=debug&edition=2018&gist=a8549057f0827bf3a068d8917256765a
        // is a translation of the prior helper function into an in-iterator
        // application.
        let tar_mode = entry.header().mode().ok().unwrap();
        // That said, the tarballs that are shipped way back have single-user
        // permissions:
        // -rwx------ rustbuild/rustbuild  ..... release/test-release.sh
        // so we should normalise the mode to match the previous behaviour users
        // may be expecting where the above file would end up with mode 0o755
        let u_mode = tar_mode & 0o700;
        let g_mode = (u_mode & 0o0500) >> 3;
        let o_mode = g_mode >> 3;
        let mode = u_mode | g_mode | o_mode;

        let file_size = entry.header().size()?;
        let size = std::cmp::min(IO_CHUNK_SIZE as u64, file_size);

        while !io_executor.buffer_available(size as usize) {
            flush_ios::<tar::Entry<'_, R>, _>(
                &mut *io_executor,
                &mut directories,
                None,
                &full_path,
            )?;
        }

        let mut incremental_file_sender = None;
        let mut item = match kind {
            EntryType::Directory => {
                directories.insert(full_path.to_owned(), DirStatus::Pending(Vec::new()));
                Item::make_dir(full_path.clone(), mode)
            }
            EntryType::Regular => {
                if file_size > IO_CHUNK_SIZE as u64 {
                    let (item, sender) = Item::write_file_segmented(
                        full_path.clone(),
                        mode,
                        io_executor.incremental_file_state(),
                    )?;
                    incremental_file_sender = Some(sender);
                    item
                } else {
                    let mut content = io_executor.get_buffer(size as usize);
                    entry.read_to_end(&mut content)?;
                    content = content.finished();
                    Item::write_file(full_path.clone(), mode, content)
                }
            }
            _ => bail!(format!("tar entry kind '{kind:?}' is not supported")),
        };

        let item = loop {
            // Create the full path to the entry if it does not exist already
            let full_path = item.full_path.to_owned();
            let Some(parent) = full_path.parent() else {
                // We should never see a path with no parent.
                unreachable!()
            };
            match directories.get_mut(parent) {
                None => {
                    // Tar has item before containing directory
                    // Complain about this so we can see if these exist.
                    warn!(
                        "unexpected: missing parent '{}' for '{}'",
                        parent.display(),
                        entry.path()?.display()
                    );
                    directories.insert(parent.to_owned(), DirStatus::Pending(vec![item]));
                    item = Item::make_dir(parent.to_owned(), 0o755);
                    // Check the parent's parent
                    continue;
                }
                Some(DirStatus::Exists) => {
                    break Some(item);
                }
                Some(DirStatus::Pending(pending)) => {
                    // Parent dir is being made
                    pending.push(item);
                    if incremental_file_sender.is_none() {
                        // take next item from tar
                        continue 'entries;
                    } else {
                        // don't submit a new item for processing, but do be ready to feed data to the incremental file.
                        break None;
                    }
                }
            }
        };

        if let Some(item) = item {
            // Submit the new item
            for mut item in io_executor.execute(item).collect::<Vec<_>>() {
                // TODO capture metrics
                filter_result(&mut item)?;
                trigger_children(&*io_executor, &mut directories, item)?;
            }
        }

        let mut incremental_file_sender =
            incremental_file_sender.map(|incremental_file_sender| SenderEntry {
                sender: incremental_file_sender,
                entry,
            });

        // monitor io queue and feed in the content of the file (if needed)
        while !flush_ios(
            &mut *io_executor,
            &mut directories,
            incremental_file_sender.as_mut(),
            &full_path,
        )? {}
    }

    loop {
        let mut triggered = 0;
        for mut item in io_executor.join().collect::<Vec<_>>() {
            // handle final IOs
            // TODO capture metrics
            filter_result(&mut item)?;
            triggered += trigger_children(&*io_executor, &mut directories, item)?;
        }
        if triggered == 0 {
            // None of the IO submitted before the prior join triggered any new
            // submissions
            break;
        }
    }

    Ok(())
}

//! The representation of the installed toolchain and its components.
//! `Components` and `DirectoryPackage` are the two sides of the
//! installation / uninstallation process.

use std::borrow::Cow;
use std::convert::Infallible;
use std::fmt;
use std::io::BufWriter;
use std::path::{Path, PathBuf};
use std::str::FromStr;

use anyhow::{Result, bail};

use crate::dist::component::package::{INSTALLER_VERSION, VERSION_FILE};
use crate::dist::component::transaction::Transaction;
use crate::dist::prefix::InstallPrefix;
use crate::errors::RustupError;
use crate::utils;

const COMPONENTS_FILE: &str = "components";

#[derive(Clone, Debug)]
pub struct Components {
    prefix: InstallPrefix,
}

impl Components {
    pub fn open(prefix: InstallPrefix) -> Result<Self> {
        let c = Self { prefix };

        // Validate that the metadata uses a format we know
        if let Some(v) = c.read_version()?
            && v != INSTALLER_VERSION
        {
            bail!(
                "unsupported metadata version in existing installation: {}",
                v
            );
        }

        Ok(c)
    }
    fn rel_components_file(&self) -> PathBuf {
        self.prefix.rel_manifest_file(COMPONENTS_FILE)
    }
    fn rel_component_manifest(&self, name: &str) -> PathBuf {
        self.prefix.rel_manifest_file(&format!("manifest-{name}"))
    }
    fn read_version(&self) -> Result<Option<String>> {
        let p = self.prefix.manifest_file(VERSION_FILE);
        if utils::is_file(&p) {
            Ok(Some(utils::read_file(VERSION_FILE, &p)?.trim().to_string()))
        } else {
            Ok(None)
        }
    }
    fn write_version(&self, tx: &mut Transaction) -> Result<()> {
        tx.modify_file(self.prefix.rel_manifest_file(VERSION_FILE))?;
        utils::write_file(
            VERSION_FILE,
            &self.prefix.manifest_file(VERSION_FILE),
            INSTALLER_VERSION,
        )?;

        Ok(())
    }
    pub fn list(&self) -> Result<Vec<Component>> {
        let path = self.prefix.abs_path(self.rel_components_file());
        if !utils::is_file(&path) {
            return Ok(Vec::new());
        }
        let content = utils::read_file("components", &path)?;
        Ok(content
            .lines()
            .map(|s| Component {
                components: self.clone(),
                name: s.to_owned(),
            })
            .collect())
    }
    pub(crate) fn add(&self, name: &str, tx: Transaction) -> ComponentBuilder {
        ComponentBuilder {
            components: self.clone(),
            name: name.to_owned(),
            parts: Vec::new(),
            tx,
        }
    }
    pub fn find(&self, name: &str) -> Result<Option<Component>> {
        let result = self.list()?;
        Ok(result.into_iter().find(|c| c.name() == name))
    }
    pub(crate) fn prefix(&self) -> InstallPrefix {
        self.prefix.clone()
    }
}

pub(crate) struct ComponentBuilder {
    components: Components,
    name: String,
    parts: Vec<ComponentPart>,
    tx: Transaction,
}

impl ComponentBuilder {
    pub(crate) fn copy_file(&mut self, path: PathBuf, src: &Path) -> Result<()> {
        self.parts.push(ComponentPart {
            kind: ComponentPartKind::File,
            path: path.clone(),
        });
        self.tx.copy_file(&self.name, path, src)
    }
    pub(crate) fn copy_dir(&mut self, path: PathBuf, src: &Path) -> Result<()> {
        self.parts.push(ComponentPart {
            kind: ComponentPartKind::Dir,
            path: path.clone(),
        });
        self.tx.copy_dir(&self.name, path, src)
    }
    pub(crate) fn move_file(&mut self, path: PathBuf, src: &Path) -> Result<()> {
        self.parts.push(ComponentPart {
            kind: ComponentPartKind::File,
            path: path.clone(),
        });
        self.tx.move_file(&self.name, path, src)
    }
    pub(crate) fn move_dir(&mut self, path: PathBuf, src: &Path) -> Result<()> {
        self.parts.push(ComponentPart {
            kind: ComponentPartKind::Dir,
            path: path.clone(),
        });
        self.tx.move_dir(&self.name, path, src)
    }
    pub(crate) fn finish(mut self) -> Result<Transaction> {
        // Write component manifest
        let path = self.components.rel_component_manifest(&self.name);
        let abs_path = self.components.prefix.abs_path(&path);
        let mut file = BufWriter::new(self.tx.add_file(&self.name, path)?);
        for part in self.parts {
            // FIXME: This writes relative paths to the component manifest,
            // but rust-installer writes absolute paths.
            utils::write_line("component", &mut file, &abs_path, &part.encode())?;
        }

        // Add component to components file
        let path = self.components.rel_components_file();
        let abs_path = self.components.prefix.abs_path(&path);
        self.tx.modify_file(path)?;
        utils::append_file("components", &abs_path, &self.name)?;

        // Drop in the version file for future use
        self.components.write_version(&mut self.tx)?;

        Ok(self.tx)
    }
}

#[derive(Debug)]
pub struct ComponentPart {
    /// Kind of the [`ComponentPart`], such as `"file"` or `"dir"`.
    pub kind: ComponentPartKind,
    /// Relative path of the [`ComponentPart`],
    /// with components separated by the system's main path separator.
    pub path: PathBuf,
}

#[derive(Debug, PartialEq)]
pub enum ComponentPartKind {
    File,
    Dir,
    Unknown(String),
}

impl fmt::Display for ComponentPartKind {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::File => write!(f, "file"),
            Self::Dir => write!(f, "dir"),
            Self::Unknown(s) => write!(f, "{s}"),
        }
    }
}

impl FromStr for ComponentPartKind {
    type Err = Infallible;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s {
            "file" => Ok(Self::File),
            "dir" => Ok(Self::Dir),
            s => Ok(Self::Unknown(s.to_owned())),
        }
    }
}

impl ComponentPart {
    const PATH_SEP_MANIFEST: &str = "/";
    const PATH_SEP_MAIN: &str = std::path::MAIN_SEPARATOR_STR;

    pub(crate) fn encode(&self) -> String {
        let mut buf = self.kind.to_string();
        buf.push(':');
        // Lossy conversion is safe here because we assume that `path` comes from
        // `ComponentPart::decode()`, i.e. from calling `Path::from()` on a `&str`.
        let mut path = self.path.to_string_lossy();
        if Self::PATH_SEP_MAIN != Self::PATH_SEP_MANIFEST {
            path = Cow::Owned(path.replace(Self::PATH_SEP_MAIN, Self::PATH_SEP_MANIFEST));
        };
        buf.push_str(&path);
        buf
    }

    pub(crate) fn decode(line: &str) -> Option<Self> {
        let pos = line.find(':')?;
        let mut path_str = Cow::Borrowed(&line[(pos + 1)..]);
        if Self::PATH_SEP_MANIFEST != Self::PATH_SEP_MAIN {
            path_str = Cow::Owned(path_str.replace(Self::PATH_SEP_MANIFEST, Self::PATH_SEP_MAIN));
        };
        Some(Self {
            // FIXME: Use `.into_ok()` when it's available.
            kind: line[0..pos].parse().unwrap(),
            path: PathBuf::from(path_str.as_ref()),
        })
    }
}

#[derive(Clone, Debug)]
pub struct Component {
    components: Components,
    name: String,
}

impl Component {
    pub(crate) fn manifest_name(&self) -> String {
        format!("manifest-{}", self.name)
    }
    pub(crate) fn manifest_file(&self) -> PathBuf {
        self.components.prefix.manifest_file(&self.manifest_name())
    }
    pub(crate) fn rel_manifest_file(&self) -> PathBuf {
        self.components
            .prefix
            .rel_manifest_file(&self.manifest_name())
    }
    pub(crate) fn name(&self) -> &str {
        &self.name
    }
    pub(crate) fn parts(&self) -> Result<Vec<ComponentPart>> {
        let mut result = Vec::new();
        for line in utils::read_file("component", &self.manifest_file())?.lines() {
            result.push(
                ComponentPart::decode(line)
                    .ok_or_else(|| RustupError::CorruptComponent(self.name.clone()))?,
            );
        }
        Ok(result)
    }
    pub fn uninstall(&self, mut tx: Transaction) -> Result<Transaction> {
        // Update components file
        let path = self.components.rel_components_file();
        let abs_path = self.components.prefix.abs_path(&path);
        let temp = tx.temp().new_file()?;
        utils::filter_file("components", &abs_path, &temp, |l| l != self.name)?;
        tx.modify_file(path)?;
        utils::rename("components", &temp, &abs_path, tx.permit_copy_rename)?;

        // TODO: If this is the last component remove the components file
        // and the version file.

        // Track visited directories
        use std::collections::HashSet;
        use std::collections::hash_set::IntoIter;
        use std::fs::read_dir;

        // dirs will contain the set of longest disjoint directory paths seen
        // ancestors help in filtering seen paths and constructing dirs
        // All seen paths must be relative to avoid surprises
        struct PruneSet {
            dirs: HashSet<PathBuf>,
            ancestors: HashSet<PathBuf>,
            prefix: PathBuf,
        }

        impl PruneSet {
            fn seen(&mut self, mut path: PathBuf) {
                if !path.is_relative() || !path.pop() {
                    return;
                }
                if self.dirs.contains(&path) || self.ancestors.contains(&path) {
                    return;
                }
                self.dirs.insert(path.clone());
                while path.pop() {
                    if path.file_name().is_none() {
                        break;
                    }
                    if self.dirs.contains(&path) {
                        self.dirs.remove(&path);
                    }
                    if self.ancestors.contains(&path) {
                        break;
                    }
                    self.ancestors.insert(path.clone());
                }
            }
        }

        struct PruneIter {
            iter: IntoIter<PathBuf>,
            path_buf: Option<PathBuf>,
            prefix: PathBuf,
        }

        impl IntoIterator for PruneSet {
            type Item = PathBuf;
            type IntoIter = PruneIter;

            fn into_iter(self) -> Self::IntoIter {
                PruneIter {
                    iter: self.dirs.into_iter(),
                    path_buf: None,
                    prefix: self.prefix,
                }
            }
        }

        // Returns only empty directories
        impl Iterator for PruneIter {
            type Item = PathBuf;

            fn next(&mut self) -> Option<Self::Item> {
                self.path_buf = match self.path_buf {
                    None => self.iter.next(),
                    Some(_) => {
                        let mut path_buf = self.path_buf.take().unwrap();
                        match path_buf.file_name() {
                            Some(_) => {
                                if path_buf.pop() {
                                    Some(path_buf)
                                } else {
                                    None
                                }
                            }
                            None => self.iter.next(),
                        }
                    }
                };
                self.path_buf.as_ref()?;
                let full_path = self.prefix.join(self.path_buf.as_ref().unwrap());
                let empty = match read_dir(full_path) {
                    Ok(dir) => dir.count() == 0,
                    Err(_) => false,
                };
                if empty {
                    self.path_buf.clone()
                } else {
                    // No dir above can be empty, go to next path in dirs
                    self.path_buf = None;
                    self.next()
                }
            }
        }

        // Remove parts
        let mut pset = PruneSet {
            dirs: HashSet::new(),
            ancestors: HashSet::new(),
            prefix: self.components.prefix.abs_path(""),
        };
        for part in self.parts()?.into_iter().rev() {
            match part.kind {
                ComponentPartKind::File => tx.remove_file(&self.name, part.path.clone())?,
                ComponentPartKind::Dir => tx.remove_dir(&self.name, part.path.clone())?,
                _ => return Err(RustupError::CorruptComponent(self.name.clone()).into()),
            }
            pset.seen(part.path);
        }
        for empty_dir in pset {
            tx.remove_dir(&self.name, empty_dir)?;
        }

        // Remove component manifest
        tx.remove_file(&self.name, self.rel_manifest_file())?;

        Ok(tx)
    }
}

